package com.example.taskmanager.service;
import com.example.taskmanager.model.Task; import com.example.taskmanager.repository.TaskRepository; import org.springframework.beans.factory.annotation.*; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import java.time.*;
@Service public class ReminderService { private final TaskRepository repo; private final JavaMailSender mail; @Value("${spring.mail.username:}") String from; public ReminderService(TaskRepository r,JavaMailSender m){repo=r;mail=m;}
 @Scheduled(fixedRate=3600000) public void sendReminders(){LocalDateTime now=LocalDateTime.now(), until=now.plusDays(1).plusMinutes(5); for(Task t:repo.findAll()){if(t.isReminderSent()||"COMPLETED".equals(t.getStatus()))continue; if(t.getDeadline().isAfter(now.plusHours(23))&&t.getDeadline().isBefore(until)){try{SimpleMailMessage msg=new SimpleMailMessage();msg.setFrom(from);msg.setTo(t.getUser().getEmail());msg.setSubject("Task Reminder: "+t.getTitle());msg.setText("Your task is due within 24 hours.\n\nTask: "+t.getTitle()+"\nPriority: "+t.getPriority()+"\nDeadline: "+t.getDeadline()+"\n\nPlease complete it before the deadline.");mail.send(msg);t.setReminderSent(true);repo.save(t);}catch(Exception ignored){}}}}
}
